<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';
try{$viewer=(int)(current_user()['id']??0);$sa=v17_profile_sql('s.user_id',$viewer);$ra=v17_profile_sql('r.user_id',$viewer);$ca=v17_profile_sql('c.streamer_user_id',$viewer).' AND '.v17_profile_sql('c.created_by_user_id',$viewer);$q=trim((string)($_GET['q']??''));if(text_len($q)<1)json_response(['streams'=>[],'channels'=>[],'categories'=>[],'recordings'=>[],'clips'=>[]]);$like='%'.text_substr($q,0,80).'%';
$st=db()->prepare("SELECT s.*,u.username,u.display_name,u.avatar_url,(SELECT COUNT(*) FROM stream_viewers sv WHERE sv.stream_id=s.id AND sv.last_seen_at>=NOW()-INTERVAL 20 SECOND) viewer_count_live FROM streams s JOIN users u ON u.id=s.user_id WHERE s.is_live=1 AND {$sa} AND (s.title LIKE ? OR s.category LIKE ? OR u.username LIKE ? OR u.display_name LIKE ?) ORDER BY viewer_count_live DESC LIMIT 8");$st->execute([$like,$like,$like,$like]);$streams=array_map('map_stream',$st->fetchAll());
$ch=db()->prepare('SELECT id,public_id,username,display_name,avatar_url,bio FROM users WHERE account_status=\'active\' AND (public_id=? OR username LIKE ? OR display_name LIKE ?) ORDER BY (public_id=?) DESC,id DESC LIMIT 8');$ch->execute([$q,$like,$like,$q]);
$ca=db()->prepare('SELECT id,name,slug,icon FROM categories WHERE is_active=1 AND name LIKE ? ORDER BY sort_order LIMIT 8');$ca->execute([$like]);
$r=db()->prepare("SELECT r.id,r.title,r.thumbnail_url,r.duration_seconds,u.username,u.display_name FROM recordings r JOIN users u ON u.id=r.user_id WHERE r.visibility='public' AND {$ra} AND r.status='ready' AND (r.title LIKE ? OR u.display_name LIKE ?) ORDER BY r.id DESC LIMIT 8");$r->execute([$like,$like]);
$c=db()->prepare("SELECT c.id,c.title,c.thumbnail_url,c.duration_seconds,u.username,u.display_name FROM clips c JOIN users u ON u.id=c.streamer_user_id WHERE c.visibility='public' AND {$ca} AND (c.title LIKE ? OR u.display_name LIKE ?) ORDER BY c.id DESC LIMIT 8");$c->execute([$like,$like]);
json_response(['streams'=>$streams,'channels'=>array_map(static fn($x)=>['id'=>(int)$x['id'],'publicId'=>(string)($x['public_id']??''),'username'=>$x['username'],'displayName'=>$x['display_name'],'avatarUrl'=>$x['avatar_url']?:null,'bio'=>$x['bio']],$ch->fetchAll()),'categories'=>$ca->fetchAll(),'recordings'=>v17_legacy_media($r->fetchAll(),'recording'),'clips'=>v17_legacy_media($c->fetchAll(),'clip')]);
}catch(Throwable $e){json_response(['message'=>'Arama yapılamadı.'],500);}
